require_once __DIR__.'/functions.php';$u=require_login();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM files WHERE id=? AND user_id=?');$s->execute([$id,$u['id']]);$f=$s->fetch();if(!$f){http_response_code(404);exit('File tidak ditemukan.');}$path=STORAGE_DIR.'/'.$f['stored_name'].'.enc';if(!is_file($path)){http_response_code(404);exit('Data file tidak ditemukan di penyimpanan.');}try{$plain=decrypt_file(file_get_contents($path));}catch(Throwable $e){http_response_code(500);exit('File tidak dapat didekripsi. Periksa APP_KEY.');}header('Content-Type: application/octet-stream');header('Content-Length: '.strlen($plain));header('Content-Disposition: attachment; filename="'.rawurlencode($f['original_name']).'"');header('X-Content-Type-Options: nosniff');echo $plain;
